const redis = require('ioredis');
const client = new redis();
const IDEMPOTENCY_TTL_SECONDS = 86400; // 24 hours

async function processPaymentMessage(msg) {
  const key = `paid:${msg.orderId}`;
  const alreadyProcessed = await client.get(key);

  if (alreadyProcessed) {
    console.log('Duplicate message skipped');
    return { skipped: true };
  }

  await db.payments.create({
    orderId: msg.orderId,
    amount: msg.amount,
    status: 'paid'
  });

  await client.set(key, '1', 'EX', IDEMPOTENCY_TTL_SECONDS);
  return { skipped: false };
}

public class PaymentService
{
    private readonly AppDbContext _db;

    public async Task ProcessAsync(ProcessPaymentCommand cmd)
    {
        try
        {
            var payment = new Payment
            {
                Id = cmd.PaymentId,
                OrderId = cmd.OrderId,
                Amount = cmd.Amount,
                ProcessedAt = DateTime.UtcNow
            };

            await _db.Payments.AddAsync(payment);
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException ex) when
            (IsUniqueConstraintViolation(ex))
        {
            _logger.LogWarning("Duplicate payment {PaymentId} ignored", cmd.PaymentId);
        }
    }

    private bool IsUniqueConstraintViolation(DbUpdateException ex)
        => ex.InnerException is PostgresException pg &&
           pg.SqlState == PostgresErrorCodes.UniqueViolation;
}
